type allocationDefaultWhere[Q psql.Filterable] struct {
	cols        allocationDefaultColumns
	HouseholdID psql.WhereMod[Q, uuid.UUID]
	Version     psql.WhereMod[Q, int64]
	PoolID      psql.WhereMod[Q, uuid.UUID]
	Weight      psql.WhereMod[Q, int64]
	CreatedAt   psql.WhereMod[Q, time.Time]
	R           allocationDefaultWhereR[Q]
}

func (allocationDefaultWhere[Q]) AliasedAs(alias string) allocationDefaultWhere[Q] {
	return buildAllocationDefaultWhere[Q](buildAllocationDefaultColumns(alias))
}

func buildAllocationDefaultWhere[Q psql.Filterable](cols allocationDefaultColumns) allocationDefaultWhere[Q] {
	return allocationDefaultWhere[Q]{
		cols:        cols,
		HouseholdID: psql.Where[Q, uuid.UUID](cols.HouseholdID.Expression),
		Version:     psql.Where[Q, int64](cols.Version.Expression),
		PoolID:      psql.Where[Q, uuid.UUID](cols.PoolID.Expression),
		Weight:      psql.Where[Q, int64](cols.Weight.Expression),
		CreatedAt:   psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		R:           allocationDefaultWhereR[Q]{cols: cols},
	}
}

// allocationDefaultWhereR holds the relationship-based filters of
// allocationDefaultWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type allocationDefaultWhereR[Q psql.Filterable] struct {
	cols allocationDefaultColumns
}

// HasHousehold filters parents that have a matching Household using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Households).
func (w allocationDefaultWhereR[Q]) HasHousehold(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Households.NameExpr()),
		sm.Where(Households.Columns.ID.EQ(w.cols.HouseholdID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasPool filters parents that have a matching Pool using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Pools).
func (w allocationDefaultWhereR[Q]) HasPool(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Pools.NameExpr()),
		sm.Where(Pools.Columns.HouseholdID.EQ(w.cols.HouseholdID)),
		sm.Where(Pools.Columns.ID.EQ(w.cols.PoolID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *AllocationDefault) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("allocationDefault cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.AllocationDefaults = AllocationDefaultSlice{o}
		}
		return nil
	case "Pool":
		rel, ok := retrieved.(*Pool)
		if !ok {
			return fmt.Errorf("allocationDefault cannot load %T as %q", retrieved, name)
		}

		o.R.Pool = rel
		o.R.Loaded.Pool = true

		if rel != nil {
			rel.R.AllocationDefaults = AllocationDefaultSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("allocationDefault has no relationship %q", name)
	}
}

type allocationDefaultPreloader struct {
	Household func(...psql.PreloadOption) psql.Preloader
	Pool      func(...psql.PreloadOption) psql.Preloader
}

func buildAllocationDefaultPreloader() allocationDefaultPreloader {
	return allocationDefaultPreloader{
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        AllocationDefaults,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
		Pool: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Pool, PoolSlice](psql.PreloadRel{
				Name: "Pool",
				Sides: []psql.PreloadSide{
					{
						From:        AllocationDefaults,
						To:          Pools,
						FromColumns: []string{"household_id", "pool_id"},
						ToColumns:   []string{"household_id", "id"},
					},
				},
			}, Pools.Columns.Names(), poolScanMapperNullable, opts...)
		},
	}
}

type allocationDefaultThenLoader[Q orm.Loadable] struct {
	Household func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Pool      func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildAllocationDefaultThenLoader[Q orm.Loadable]() allocationDefaultThenLoader[Q] {
	type HouseholdLoadInterface interface {
		LoadHousehold(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PoolLoadInterface interface {
		LoadPool(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return allocationDefaultThenLoader[Q]{
		Household: thenLoadBuilder[Q](
			"Household",
			func(ctx context.Context, exec bob.Executor, retrieved HouseholdLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadHousehold(ctx, exec, mods...)
			},
		),
		Pool: thenLoadBuilder[Q](
			"Pool",
			func(ctx context.Context, exec bob.Executor, retrieved PoolLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadPool(ctx, exec, mods...)
			},
		),
	}
}

// LoadHousehold loads the allocationDefault's Household into the .R struct
func (o *AllocationDefault) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Household = nil
	o.R.Loaded.Household = false

	related, err := o.Household(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.AllocationDefaults = AllocationDefaultSlice{o}

	o.R.Household = related
	o.R.Loaded.Household = true
	return nil
}

// LoadHousehold loads the allocationDefault's Household into the .R struct
func (os AllocationDefaultSlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	allocationDefaultByKey := make(map[uuid.UUID][]*AllocationDefault, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		allocationDefaultByKey[o.HouseholdID] = append(allocationDefaultByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := allocationDefaultByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.AllocationDefaults = append(rel.R.AllocationDefaults, o)

			o.R.Household = rel

		}
	}

	return nil
}

// LoadPool loads the allocationDefault's Pool into the .R struct
func (o *AllocationDefault) LoadPool(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Pool = nil
	o.R.Loaded.Pool = false

	related, err := o.Pool(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.AllocationDefaults = AllocationDefaultSlice{o}

	o.R.Pool = related
	o.R.Loaded.Pool = true
	return nil
}

// LoadPool loads the allocationDefault's Pool into the .R struct
func (os AllocationDefaultSlice) LoadPool(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	pools, err := os.Pool(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Pool = nil
		o.R.Loaded.Pool = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range pools {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.PoolID == rel.ID) {
				continue
			}

			rel.R.AllocationDefaults = append(rel.R.AllocationDefaults, o)

			o.R.Pool = rel
			break
		}
	}

	return nil
}

type allocationDefaultJoins[Q dialect.Joinable] struct {
	typ       string
	Household modAs[Q, householdColumns]
	Pool      modAs[Q, poolColumns]
}

func (j allocationDefaultJoins[Q]) aliasedAs(alias string) allocationDefaultJoins[Q] {
	return buildAllocationDefaultJoins[Q](buildAllocationDefaultColumns(alias), j.typ)
}

func buildAllocationDefaultJoins[Q dialect.Joinable](cols allocationDefaultColumns, typ string) allocationDefaultJoins[Q] {
	return allocationDefaultJoins[Q]{
		typ: typ,
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		Pool: modAs[Q, poolColumns]{
			c: Pools.Columns,
			f: func(to poolColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Pools.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.PoolID),
					))
				}

				return mods
			},
		},
	}
}
